#!/usr/bin/env node
// Generate native-hooks adapters for every method of the given classes, from
// the name table (docs/rust-plan/phase1-name-table.tsv) and each body's Rust
// signature. Output: crates/native-hooks/src/generated.rs (do not edit by hand).
//
//   node tools/gen-native-adapters.mjs dActor_c dEn_c ...
//
// An adapter reads integer and pointer arguments from r3.. and float ones
// from f1.., in order (the EABI for these signatures), runs the body under the
// guest runtime and returns its value for r3. Bodies returning a float are
// left out: the checker compares r3 and RAM, not f1. So are bodies whose
// signature has a type the adapter cannot read, and the addresses listed in
// HAND below, which lib.rs registers itself.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'crates', 'native-hooks', 'src', 'generated.rs');
const classes = new Set(process.argv.slice(2));
if (!classes.size) {
  console.error('usage: node tools/gen-native-adapters.mjs <class>...');
  process.exit(1);
}

// Registered by hand in crates/native-hooks/src/lib.rs.
const HAND = new Set(
  [...fs.readFileSync(path.join(ROOT, 'crates', 'native-hooks', 'src', 'lib.rs'), 'utf8')
    .matchAll(/register_native(?:_void)?\(0x([0-9A-F]{4})_([0-9A-F]{4})/g)]
    .map((m) => (m[1] + m[2]).toLowerCase()),
);

const INT = new Set(['u32', 'i32', 'usize', 'isize', 'u16', 'i16', 'u8', 'i8', 'bool']);
const FLOAT = new Set(['f32', 'f64']);
const rows = fs.readFileSync(path.join(ROOT, 'docs', 'rust-plan', 'phase1-name-table.tsv'), 'utf8')
  .trim().split('\n').slice(1).map((l) => l.split('\t'));

const out = [];
const regs = [];
const skipped = [];
const fileCache = {};
for (const r of rows) {
  const [, module, address, , rustFile, currentName, , display, owner] = r;
  if (module !== 'main' || !classes.has(owner)) continue;
  const addr = address.replace(/^0x/, '').toLowerCase();
  if (HAND.has(addr)) continue;
  const src = (fileCache[rustFile] ??= fs.readFileSync(path.join(ROOT, rustFile), 'utf8'));
  const m = src.match(new RegExp(String.raw`pub unsafe fn ` + currentName + String.raw`\s*\(([^)]*)\)\s*(->\s*([^{]+?))?\s*\{`));
  if (!m) { skipped.push(`${address} ${display}: no public body ${currentName}`); continue; }
  const params = m[1].split(',').map((s) => s.trim()).filter(Boolean).map((p) => {
    const i = p.indexOf(':');
    return { name: p.slice(0, i).trim(), ty: p.slice(i + 1).trim() };
  });
  const ret = (m[3] || '()').trim();
  if (FLOAT.has(ret)) { skipped.push(`${address} ${display}: returns ${ret}`); continue; }
  if (ret !== '()' && !INT.has(ret)) { skipped.push(`${address} ${display}: returns ${ret}`); continue; }
  let g = 3, f = 1, ok = true;
  const args = params.map((p) => {
    if (INT.has(p.ty)) return p.ty === 'bool' ? `gprs[${g++}] & 0xFF != 0` : `gprs[${g++}] as ${p.ty}`;
    if (/^\*(mut|const) /.test(p.ty)) return `gprs[${g++}] as usize as ${p.ty}`;
    if (FLOAT.has(p.ty)) return `fprs[${f++}][0] as ${p.ty}`;
    ok = false;
    return '';
  });
  if (!ok || g > 11 || f > 9) { skipped.push(`${address} ${display}: arguments (${m[1].replace(/\s+/g, ' ')})`); continue; }
  const mod = rustFile.replace(/^src\//, '').replace(/\.rs$/, '').replace(/\//g, '::');
  const call = `nsmbw::${mod}::${currentName}(${args.join(', ')})`;
  const body = ret === '()' ? `${call};\n        0` : ret === 'bool' ? `u32::from(${call})` : `${call} as u32`;
  const fname = `n_${addr}`;
  out.push(
    `/// \`${display}\` (\`${address}\`).\n` +
    `unsafe fn ${fname}(\n    runtime: &mut (dyn GuestRuntime + 'static),\n    gprs: &[u32; 32],\n    fprs: &[[f64; 2]; 32],\n) -> u32 {\n` +
    `    let _ = (gprs, fprs);\n    nsmbw::platform::with_guest_runtime(runtime, || {\n        ${body}\n    })\n}\n`,
  );
  regs.push(`    (0x${addr.slice(0, 4).toUpperCase()}_${addr.slice(4).toUpperCase()}, ${fname}, ${ret === '()'}),`);
}

const text =
  `//! Generated by \`node tools/gen-native-adapters.mjs ${[...classes].join(' ')}\`: do not edit.\n` +
  `//! One adapter per method of those classes with a Rust body (see the tool).\n\n` +
  `#![allow(clippy::unnecessary_cast)]\n\n` +
  `use guest_cpu::GuestRuntime;\nuse hle_os::NativeBody;\n\n` +
  out.join('\n') +
  `\n/// Address, adapter, and whether the function returns nothing.\n` +
  `pub const BODIES: &[(u32, NativeBody, bool)] = &[\n${regs.join('\n')}\n];\n`;
fs.writeFileSync(OUT, text);
console.log(`${regs.length} adapters, ${skipped.length} left out`);
for (const s of skipped) console.log('  left out: ' + s);
